<script setup lang="ts">
import { computed, defineAsyncComponent, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { Activity, ArrowDownToLine, ArrowRight, ArrowUpRight, Bell, BookOpen, CalendarDays, ChartCandlestick, ChartNoAxesCombined, Check, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clock3, Database, FileText, FlaskConical, Globe2, LayoutDashboard, ListFilter, LoaderCircle, LockKeyhole, Menu, MoreHorizontal, Plus, RefreshCw, Search, Settings2, ShieldCheck, Sparkles, Star, Terminal, Trash2, Wallet, X, Zap } from 'lucide-vue-next'
import { api, post, download, setToken } from './api'
import ConfirmDialog from './components/ConfirmDialog.vue'
const props = defineProps<{ publicMode?: boolean, publicUser?: any }>()
const emit = defineEmits<{ 'open-settings': [] }>()
const confirmText = ref('')
let confirmResolve: ((answer: boolean) => void) | null = null
function confirmForUser(message: string): Promise<boolean> { if (!props.publicMode) return Promise.resolve(window.confirm(message)); confirmText.value = message; return new Promise(resolve => { confirmResolve = resolve }) }
function settleConfirm(answer: boolean) { confirmText.value = ''; confirmResolve?.(answer); confirmResolve = null }
const ResearchChart = defineAsyncComponent(() => import('./components/ResearchChart.vue'))
const nav = [
  { id: 'dashboard', name: '研究总览', icon: LayoutDashboard }, { id: 'watchlist', name: '自选证券', icon: Star }, { id: 'market', name: '市场行情', icon: ChartCandlestick }, { id: 'metals', name: '黄金与白银', icon: Globe2 },
  { id: 'candidates', name: '候选研究', icon: Sparkles }, { id: 'reports', name: 'AI 研究报告', icon: FileText }, { id: 'simulation', name: '模拟交易', icon: Wallet }, { id: 'backtest', name: '回测实验', icon: FlaskConical }, { id: 'review', name: '周度复盘', icon: BookOpen }, { id: 'jobs', name: '任务中心', icon: Clock3 }, { id: 'settings', name: props.publicMode ? '个人偏好' : '系统设置', icon: Settings2 },
]
const page = ref(location.hash.slice(1) || 'dashboard')
const sidebarOpen = ref(false), loading = ref(true), ready = ref(false), busy = ref(false)
const error = ref(''), toast = ref(''), showNotifications = ref(false), requiresLogin = ref(false), role = ref('admin')
const dashboard = ref<any>(null), model = ref<any>({ available: false, message: '正在检查模型' }), config = ref<any>(null), runtime = ref<any>(null)
const reports = ref<any[]>([]), jobData = ref<any>({ jobs: [], logs: [], schedule: { plans: [] } }), portfolio = ref<any>({ accounts: [], orders: [], ledger: [] }), experiments = ref<any[]>([]), backups = ref<any[]>([])
const selectedReport = ref<any>(null), selectedBacktest = ref<any>(null), detail = ref<any>(null), detailId = ref(''), timeframe = ref('1d'), lowerIndicator = ref('volume')
const search = ref(''), group = ref('全部'), statusFilter = ref('全部'), reportMode = ref(''), reportSearch = ref(''), activeIndex = ref('SH:000001'), accountTab = ref('orders')
const modal = ref(''), form = ref<any>({}), modalError = ref(''), budget = ref<any>(null), budgetForm = ref({ price: 0, quantity: 100 }), importFile = ref<HTMLInputElement>(), barsFile = ref<HTMLInputElement>()
const testParams = ref<any>({ instrument_id: 'SH:603126', initial_cash: 10000, fast: 5, slow: 20, train_ratio: 0.7, stop_loss_pct: 0.05, strict: true, start_date: '', end_date: '' })
let timer: ReturnType<typeof setInterval>, toastTimer: ReturnType<typeof setTimeout>
const canEdit = computed(() => props.publicMode || role.value === 'admin')
const canMaintain = computed(() => !props.publicMode ? canEdit.value : props.publicUser?.role === 'admin')
const title = computed(() => nav.find(n => n.id === page.value)?.name || '研究总览')
const watchlist = computed<any[]>(() => dashboard.value?.watchlist || [])
const groups = computed(() => ['全部', ...new Set(watchlist.value.map(r => r.group_name))])
const filteredWatch = computed(() => watchlist.value.filter(r => (group.value === '全部' || r.group_name === group.value) && (!search.value || (r.symbol + r.name + r.group_name).toLowerCase().includes(search.value.toLowerCase())) && (statusFilter.value === '全部' || (statusFilter.value === '待核验' ? r.exclusion_reasons.length > 0 : !r.exclusion_reasons.length))))
const indices = computed(() => props.publicMode ? (dashboard.value?.indices || []) : watchlist.value.filter(r => r.asset_class === 'index'))
const currentIndex = computed(() => indices.value.find((r: any) => r.id === activeIndex.value))
const latestReport = computed(() => dashboard.value?.reports?.[0])
const visibleReports = computed(() => reports.value.filter(r => (!reportMode.value || r.mode === reportMode.value) && (r.report_date + r.summary).includes(reportSearch.value)))
const metalNames: Record<string, string> = { 'FX:XAUUSD': '伦敦金现货', 'FX:XAGUSD': '伦敦银现货', 'SHFE:AU0': '沪金主力连续', 'SHFE:AG0': '沪银主力连续' }
const statuses: Record<string, string> = { unknown: '未核验', active: '正常', suspended: '停牌', delisted: '退市', queued: '排队中', running: '运行中', success: '已完成', failed: '失败', partial: '部分完成', interrupted: '已中断', missed: '错过执行', pending: '待成交', filled: '已成交', cancelled: '已撤销', rejected: '已拒绝', unavailable: '不可用' }
const modeNames: Record<string, string> = { standard: '标准版早报', full: '完整版复盘', closing: '收盘跟踪', sync: '全池数据同步', match: '模拟撮合', metals: '金银行情', backup: '数据备份' }
const fmt = (v: any, digits = 2) => v === null || v === undefined || v === '' ? '—' : Number(v).toLocaleString('zh-CN', { minimumFractionDigits: digits, maximumFractionDigits: digits })
const dt = (v: any) => !v ? '尚无记录' : Number.isNaN(new Date(v).getTime()) ? String(v).replace('T', ' ').slice(0, 19) : new Intl.DateTimeFormat('sv-SE', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }).format(new Date(v))
const pct = (v: any) => v === null || v === undefined ? '—' : (Number(v) > 0 ? '+' : '') + Number(v).toFixed(2) + '%'
const direction = (v: any) => Number(v) > 0 ? 'up' : Number(v) < 0 ? 'down' : ''
const dateText = computed(() => new Intl.DateTimeFormat('zh-CN', { year: 'numeric', month: 'long', day: 'numeric', weekday: 'long', timeZone: 'Asia/Shanghai' }).format(new Date(dashboard.value?.time || Date.now())))
function go(id: string) { if (props.publicMode && id === 'settings') { emit('open-settings'); return }; page.value = id; location.hash = id; sidebarOpen.value = false; selectedReport.value = null }
function syncHash() { const id = location.hash.slice(1).split('?')[0]; if (nav.some(n => n.id === id) && id !== page.value) { page.value = id; selectedReport.value = null; sidebarOpen.value = false } }
function notify(message: string) { toast.value = message; clearTimeout(toastTimer); toastTimer = setTimeout(() => toast.value = '', 5000) }
async function action(fn: () => Promise<any>, success = '') { busy.value = true; error.value = ''; try { const result = await fn(); if (success) notify(success); return result } catch (e: any) { error.value = e.message; return null } finally { busy.value = false } }
async function refreshBase() { dashboard.value = await api('/dashboard') }
async function loadPage() {
  if (!ready.value) return
  error.value = ''
  try {
    if (['reports', 'review', 'candidates'].includes(page.value)) reports.value = await api('/reports' + (page.value === 'review' ? '?mode=full' : ''))
    if (page.value === 'jobs') jobData.value = await api('/jobs')
    if (page.value === 'simulation' || page.value === 'review') portfolio.value = await api('/simulation')
    if (page.value === 'backtest' || page.value === 'review') experiments.value = await api('/backtests')
    if (page.value === 'settings') { const r = await api('/settings'); config.value = r.settings; runtime.value = r; backups.value = await api('/backups') }
    if (page.value === 'dashboard' || page.value === 'market') await loadIndex()
  } catch (e: any) { error.value = e.message }
}
const indexData = ref<any>(null)
async function loadIndex() { indexData.value = await api('/instruments/' + encodeURIComponent(activeIndex.value)) }
async function initialize() {
  try {
    if (props.publicMode) {
      role.value = props.publicUser?.role || 'user'; requiresLogin.value = false
      await refreshBase(); model.value = await api('/model/health'); config.value = (await api('/settings')).settings
      if (page.value === 'settings') page.value = 'dashboard'
      ready.value = true; await loadPage(); return
    }
    const s = await api('/session')
    if (s.requires_login && !sessionStorage.getItem('stockai-token')) { requiresLogin.value = true; return }
    if (s.token) { setToken(s.token); role.value = s.role }
    else role.value = sessionStorage.getItem('stockai-role') || 'reader'
    const result = await Promise.allSettled([refreshBase(), api('/model/health'), api('/settings')])
    if (result[0].status === 'rejected') { requiresLogin.value = true; throw result[0].reason }
    if (result[1].status === 'fulfilled') model.value = result[1].value
    if (result[2].status === 'fulfilled') { config.value = result[2].value.settings; runtime.value = result[2].value }
    ready.value = true
    await loadPage()
  } catch (e: any) { error.value = e.message } finally { loading.value = false }
}
async function login() { await action(async () => { const r = await post('/login', form.value); setToken(r.token); role.value = r.role; sessionStorage.setItem('stockai-role', r.role); requiresLogin.value = false; await initialize() }) }
async function runJob(kind: string) { await action(async () => { const r = await post('/jobs', { kind }); notify(r.status === 'success' ? '当日任务已完成，沿用归档结果' : '任务已加入队列，可在任务中心查看进度'); await refreshBase(); if (page.value === 'jobs') await loadPage() }) }
async function openDetail(id: string) { detailId.value = id; timeframe.value = '1d'; budget.value = null; detail.value = null; await action(async () => { detail.value = await api('/instruments/' + encodeURIComponent(id)); budgetForm.value = { price: detail.value.bars.at(-1)?.close || 0, quantity: detail.value.instrument.rules.lot_size } }) }
async function changeTimeframe(tf: string) { timeframe.value = tf; await action(async () => detail.value = await api('/instruments/' + encodeURIComponent(detailId.value) + '?timeframe=' + tf)) }
function openModal(name: string, initial: any = {}) { modal.value = name; form.value = structuredClone(initial); modalError.value = '' }
async function submitModal() {
  busy.value = true; modalError.value = ''
  try {
    const f = form.value
    if (modal.value === 'add') await post('/watchlist', f)
    if (modal.value === 'account') await post('/accounts', f)
    if (modal.value === 'order') await post('/orders', { ...f, stop_loss: f.stop_loss || null })
    if (modal.value === 'password') await post('/security/password', f)
    if (modal.value === 'verify') await post('/instruments/' + encodeURIComponent(detailId.value) + '/verify', f)
    if (modal.value === 'restore') await post('/backups/' + f.id + '/restore', { confirmation: f.confirmation })
    modal.value = ''; notify('已保存'); await refreshBase(); await loadPage(); if (detailId.value) await openDetail(detailId.value)
  } catch (e: any) { modalError.value = e.message } finally { busy.value = false }
}
function newOrder(id = '') { openModal('order', { client_key: crypto.randomUUID(), account_id: portfolio.value.accounts[0]?.id || '', instrument_id: id || watchlist.value.find(r => r.asset_class === 'stock')?.id || '', side: 'buy', quantity: 100, limit_price: watchlist.value.find(r => r.id === id)?.quote?.close || 0, stop_loss: null }) }
async function prepareOrder(id = '') { portfolio.value = await api('/simulation'); if (!portfolio.value.accounts.length) { openModal('account', { name: '我的模拟账户', initial_cash: null }); return } newOrder(id) }
function verifyForm() { const i = detail.value.instrument; openModal('verify', { name: i.name, status: 'active', risk_flag: 'clear', rules: { ...i.rules, verified: true }, evidence: { listing_url: i.source_url || '', status_url: '', announcement_url: '', review_note: '', ...i.evidence } }) }
async function estimate() { await action(async () => budget.value = await post('/budget', { instrument_id: detailId.value, ...budgetForm.value })) }
async function readFile(event: Event, kind: string) {
  const target = event.target as HTMLInputElement, file = target.files?.[0]
  if (!file) return
  await action(async () => { const content = await file.text(); if (kind === 'watch') { const r = await post('/watchlist/import', { content, format: file.name.endsWith('.csv') ? 'csv' : 'json' }); notify(`已导入 ${r.imported} 项，按市场与代码去重`); await refreshBase() } else if (kind === 'bars') { await post('/instruments/' + encodeURIComponent(detailId.value) + '/bars/import', { bars: JSON.parse(content), timeframe: timeframe.value === '1w' ? '1d' : timeframe.value }); await changeTimeframe(timeframe.value); notify('历史数据已导入并校验') } else { const settings = JSON.parse(content); if (await confirmForUser('确认导入配置？费用、预算和安全设置将按文件更新。')) { await api('/settings', { method: 'PUT', body: JSON.stringify({ settings, confirm: true }) }); await loadPage(); notify('配置已导入') } } })
  target.value = ''
}
async function saveSettings() { if (!await confirmForUser('确认保存设置？费用与预算会影响后续模拟和研究；局域网开关变更需重启服务。')) return; await action(async () => { const r = await api('/settings', { method: 'PUT', body: JSON.stringify({ settings: config.value, confirm: true }) }); notify(r.restart_required ? '设置已保存，重启服务后网络监听变更生效' : '设置已保存'); await refreshBase() }) }
async function runBacktest() { await action(async () => { const p = { ...testParams.value }; if (!p.start_date) delete p.start_date; if (!p.end_date) delete p.end_date; if (!p.strict && !await confirmForUser('将运行未验证实验：缺失的历史状态或公司行动可能使结果失真。继续？')) return; selectedBacktest.value = await post('/backtests', p); experiments.value = await api('/backtests'); notify('历史撮合完成，结果与数据快照已归档') }) }
async function showReport(id: string) { await action(async () => selectedReport.value = await api('/reports/' + id)) }
async function supplementReport() { if (!selectedReport.value || !await confirmForUser('使用这份报告的原始事实补充 AI？这会使用当前默认配置并可能消耗本人模型额度，原归档保持不变。')) return; await action(async () => { await post('/reports/' + selectedReport.value.id + '/supplement'); notify('已提交补充 AI，完成后将保存为新的报告版本') }) }
function reportRoute(id: string) { go('reports'); showReport(id) }
async function pin(row: any) { await action(async () => { await api('/instruments/' + encodeURIComponent(row.id), { method: 'PATCH', body: JSON.stringify({ pinned: !row.pinned }) }); await refreshBase() }) }
async function remove(row: any) { if (!await confirmForUser('从自选中移除 ' + row.name + '？历史行情和研究记录会保留。')) return; await action(async () => { await api('/watchlist/' + encodeURIComponent(row.id), { method: 'DELETE' }); await refreshBase() }) }
async function editGroup(row: any) { const v = prompt('分组名称', row.group_name); if (v?.trim()) await action(async () => { await api('/instruments/' + encodeURIComponent(row.id), { method: 'PATCH', body: JSON.stringify({ group_name: v.trim() }) }); await refreshBase() }) }
async function exportData(path: string, name: string) { await action(() => download(path, name)) }
watch(page, loadPage)
watch(activeIndex, loadIndex)
onMounted(async () => { if (!nav.some(n => n.id === page.value)) page.value = 'dashboard'; await initialize(); timer = setInterval(async () => { if (!ready.value || requiresLogin.value || modal.value || document.hidden) return; try { await refreshBase(); if (page.value === 'jobs') jobData.value = await api('/jobs'); if (page.value === 'simulation') portfolio.value = await api('/simulation'); if (['reports', 'review'].includes(page.value)) reports.value = await api('/reports' + (page.value === 'review' ? '?mode=full' : '')) } catch { /* Keep the last successful view and surface failure on explicit refresh. */ } }, 15000) })
onMounted(() => window.addEventListener('hashchange', syncHash))
onBeforeUnmount(() => { clearInterval(timer); clearTimeout(toastTimer); window.removeEventListener('hashchange', syncHash); settleConfirm(false) })
</script>

<template>
  <div v-if="loading" class="initial-loading"><div class="brand-mark"><ChartNoAxesCombined :size="24" /></div><LoaderCircle class="spin" :size="22" /><span>{{ props.publicMode ? '正在加载个人研究空间' : '正在连接本地研究服务' }}</span></div>
  <main v-else-if="requiresLogin" class="login-page"><form class="login-card" @submit.prevent="login"><div class="brand"><span class="brand-mark"><ChartNoAxesCombined /></span><b>Stock<span>AI</span></b></div><h1>连接你的研究终端</h1><p>局域网访问需要本机管理员配置的访问密码。</p><label>访问角色<select v-model="form.role" required><option value="admin">管理员</option><option value="reader">只读访问者</option></select></label><label>访问密码<input type="password" v-model="form.password" required autocomplete="current-password" /></label><p v-if="error" class="inline-error">{{ error }}</p><button class="primary" :disabled="busy">登录</button></form></main>
  <div v-else class="app-shell">
    <div v-if="sidebarOpen" class="sidebar-scrim" @click="sidebarOpen = false"></div>
    <aside class="sidebar" :class="{ open: sidebarOpen }">
      <a href="#dashboard" class="brand" @click.prevent="go('dashboard')"><span class="brand-mark"><ChartNoAxesCombined :size="23" /></span><b>Stock<span>AI</span></b><span class="version">{{ props.publicMode ? "3.0" : "2.0" }}</span></a>
      <div class="workspace"><span class="workspace-avatar">研</span><div><strong>个人研究工作台</strong><small>{{ props.publicMode ? 'PRIVATE RESEARCH SPACE' : 'LOCAL WORKSPACE' }}</small></div><ChevronDown :size="14" /></div>
      <div class="nav-caption">研究空间</div>
      <nav><template v-for="(item, idx) in nav" :key="item.id"><div v-if="idx === 6" class="nav-caption separated">策略与系统</div><button :class="['nav-item', { active: page === item.id }]" @click="go(item.id)"><component :is="item.icon" :size="18" /><span>{{ item.name }}</span><span v-if="item.id === 'candidates'" class="nav-count">{{ dashboard?.stats.candidate_count || 0 }}</span><span v-if="item.id === 'jobs' && dashboard?.jobs.some((j: any) => j.status === 'running')" class="status-dot"></span></button></template></nav>
      <div class="sidebar-bottom"><div class="local-model"><div class="model-icon"><Activity :size="18" /></div><div><strong>{{ props.publicMode ? '个人模型' : '本地模型' }}</strong><small :class="{ warning: !model.available }">{{ props.publicMode ? (model.configured ? '已配置 · 按需调用' : '未选择默认配置') : model.available ? 'Ollama 已连接' : 'Ollama 未连接' }}</small></div><span :class="['status-dot', { off: !model.available }]"></span></div><div class="sidebar-foot"><LockKeyhole :size="12" /> {{ props.publicMode ? '独立的个人研究空间' : '数据保存在本机' }} <span>{{ props.publicMode ? 'v3.0.0' : 'v2.0.0' }}</span></div></div>
    </aside>
    <div class="main-shell">
      <header class="topbar"><div class="breadcrumbs"><button class="icon-button mobile-menu" @click="sidebarOpen = true" aria-label="打开导航"><Menu :size="20" /></button><span>研究空间</span><ChevronRight :size="13" /><strong>{{ title }}</strong></div><div class="topbar-right"><span class="local-pill"><span class="status-dot"></span> {{ props.publicMode ? '个人工作台' : '本地运行' }}</span><span class="top-divider"></span><button class="icon-button notification-button" aria-label="通知" @click="showNotifications = !showNotifications"><Bell :size="18" /><i v-if="dashboard?.notifications.some((n: any) => !n.read)"></i></button><span class="user-avatar">{{ role === 'admin' ? '研' : '阅' }}</span></div></header>
      <div v-if="showNotifications" class="notification-panel panel"><div class="panel-heading"><h3>通知</h3><button class="text-button" @click="action(async () => { await post('/notifications/read'); await refreshBase() })">全部已读</button></div><p v-if="!dashboard?.notifications.length" class="muted">暂无通知</p><div v-for="n in dashboard?.notifications" :key="n.id" class="notification-item"><strong>{{ n.message }}</strong><small>{{ dt(n.ts) }}</small></div></div>
      <main class="content">
        <div v-if="error" class="error-banner" role="alert"><CircleHelp :size="17" /><span>{{ error }}</span><button class="icon-button" @click="error = ''" aria-label="关闭错误"><X :size="15" /></button></div>
        <div class="page-heading"><div><div class="eyebrow">{{ page === 'dashboard' ? 'YOUR DAILY RESEARCH' : 'STOCKAI RESEARCH WORKSPACE' }}</div><h1>{{ title }}<span v-if="page === 'dashboard'" class="heading-dot">.</span></h1><p>{{ page === 'dashboard' ? dateText + ' · 在数据与判断之间，保持清醒。' : page === 'watchlist' ? '管理你的观察范围，所有证券按代码核验。' : page === 'metals' ? '关注金银价格、报价口径与关联资产。' : page === 'simulation' ? '用虚拟资金检验计划，每一笔都有记录。' : page === 'backtest' ? '按真实历史顺序计算，保留每次实验的证据。' : page === 'reports' ? '每一份研究，都能回到它的数据来源。' : page === 'jobs' ? '采集、研究与归档，在同一个时间表上运行。' : page === 'settings' ? '配置本地模型、数据规则与研究环境。' : page === 'review' ? '回看已保存的研究、交易与策略实验。' : '价格、证据与风险，一起看。' }}</p></div><div class="heading-actions"><template v-if="['dashboard', 'candidates', 'reports', 'review'].includes(page)"><button v-if="canMaintain" class="secondary" :disabled="busy" @click="runJob('sync')"><RefreshCw :size="15" />同步数据</button><button class="primary" :disabled="busy || !canEdit" @click="runJob(page === 'review' || reportMode === 'full' ? 'full' : 'standard')"><Sparkles :size="15" />{{ page === 'review' || reportMode === 'full' ? '生成深度复盘' : '生成研究报告' }}</button></template><button v-else-if="page === 'watchlist'" class="primary" :disabled="!canEdit" @click="openModal('add', { symbol: '', market: 'SZ', name: '待核验', asset_class: 'stock', group_name: '我的自选' })"><Plus :size="16" />添加证券</button><button v-else-if="(page === 'metals' || page === 'market') && canMaintain" class="secondary" :disabled="busy" @click="runJob(page === 'metals' ? 'metals' : 'sync')"><RefreshCw :size="15" />同步行情</button><button v-else-if="page === 'simulation'" class="primary" :disabled="!canEdit" @click="prepareOrder()"><Plus :size="16" />模拟委托</button><button v-else-if="page === 'settings'" class="primary" :disabled="busy || !canEdit" @click="saveSettings"><Check :size="16" />保存设置</button></div></div>

        <template v-if="page === 'dashboard'">
          <div class="research-status"><span><span class="status-dot"></span>研究服务就绪</span><span>{{ dashboard?.calendar.is_trading_day === true ? 'A股交易日' : dashboard?.calendar.is_trading_day === false ? 'A股休市日' : '交易日历待核验' }}</span><span>最近交易日 <b>{{ dashboard?.calendar.last_completed_session || '待同步' }}</b></span><span class="status-right"><ShieldCheck :size="14" />单只含费预算 ≤ ¥{{ fmt(config?.budget || 1000, 0) }}</span></div>
          <div class="stats-grid"><article class="metric-card"><div class="metric-label">观察证券<Star :size="17" /></div><div class="metric-value">{{ dashboard?.stats.watch_count || 0 }}<span>只</span></div><div class="metric-note">A股、ETF 与跨市场观察池</div></article><article class="metric-card"><div class="metric-label">已有行情<ChartCandlestick :size="17" /></div><div class="metric-value">{{ dashboard?.stats.quote_count || 0 }}<span>/ {{ dashboard?.stats.watch_count || 0 }}</span></div><div class="metric-note">保留报价时间与来源</div></article><article class="metric-card"><div class="metric-label">通过风险核验<ShieldCheck :size="17" /></div><div class="metric-value">{{ dashboard?.stats.verified_count || 0 }}<span>只</span></div><div class="metric-note"><span class="tiny-dot amber"></span> 未知状态自动阻止入选</div></article><article class="metric-card accent-card"><div class="metric-label">本次研究候选<Sparkles :size="17" /></div><div class="metric-value">{{ dashboard?.stats.candidate_count || 0 }}<span>/ 3</span></div><button class="metric-link" @click="go('candidates')">查看筛选依据 <ArrowUpRight :size="13" /></button></article></div>
          <div class="dashboard-columns"><section class="panel market-panel"><div class="panel-heading"><div><h2>市场概览 <span class="small-badge">A 股</span></h2><p>最近已完成交易日 · 不复权收盘价</p></div><button class="text-button" @click="go('market')">全部行情 <ArrowRight :size="14" /></button></div><div class="index-tabs"><button v-for="i in indices" :key="i.id" :class="{ selected: activeIndex === i.id }" @click="activeIndex = i.id"><span>{{ i.name }}</span><strong :class="direction(i.change_pct)">{{ fmt(i.quote?.close) }}<small>{{ pct(i.change_pct) }}</small></strong></button></div><ResearchChart :bars="indexData?.bars || []" :indicators="indexData?.indicators.series || []" /><div class="chart-foot"><span class="tiny-dot"></span>{{ currentIndex?.quote ? currentIndex.quote.source + ' · ' + dt(currentIndex.quote.ts) : '行情尚未同步，图表不会使用示例价格' }}</div></section><section class="panel metals-panel"><div class="panel-heading"><div><h2>黄金与白银</h2><p>跨市场观察</p></div><span class="gold-dot"></span></div><div v-for="(m, idx) in dashboard?.metals.slice(0, 2)" :key="m.id" class="metal-summary"><div class="metal-symbol" :class="{ silver: idx === 1 }">{{ idx === 0 ? 'Au' : 'Ag' }}</div><div class="metal-summary-info"><strong>{{ metalNames[m.id] }}</strong><small>{{ idx === 0 ? 'XAU / USD' : 'XAG / USD' }}</small><small class="quote-time">{{ m.quote_time ? dt(m.quote_time).slice(5, 16) + (m.stale ? ' · 已过期' : '') : '等待报价时间' }}</small></div><div class="metal-price"><b>{{ fmt(m.price) }}</b><small>{{ m.price ? '美元 / 金衡盎司' : '数据待同步' }}</small></div></div><div class="metal-source">新浪财经 · 提供方未声明延迟 <span>Asia/Shanghai</span></div><div class="metal-ratio"><span>金银比</span><strong>{{ dashboard?.metals[0]?.price && dashboard?.metals[1]?.price && dashboard.metals[0].quote_time === dashboard.metals[1].quote_time ? fmt(dashboard.metals[0].price / dashboard.metals[1].price) : '—' }}</strong><small>仅在同一时点、同币种单位下计算</small></div><button class="metals-link" @click="go('metals')">进入贵金属专题 <ArrowUpRight :size="16" /></button></section></div>
          <div class="dashboard-columns lower-columns"><section class="panel"><div class="panel-heading"><div><h2>我的自选 <span class="muted count-text">{{ dashboard?.stats.watch_count }}</span></h2><p>从熟悉的证券开始，持续积累证据</p></div><button class="text-button" @click="go('watchlist')">管理自选 <ArrowRight :size="14" /></button></div><div class="table-scroll"><table class="watch-table"><thead><tr><th>证券 / 代码</th><th class="number">最近价格</th><th class="number">涨跌幅</th><th>核验状态</th><th class="number">预算数量</th></tr></thead><tbody><tr v-for="r in watchlist.filter(r => r.asset_class === 'stock' && ['SH', 'SZ'].includes(r.market)).slice(0, 5)" :key="r.id" @click="openDetail(r.id)" class="clickable"><td><strong>{{ r.name }}</strong><small>{{ r.symbol }} <span>{{ r.market }}</span></small></td><td class="number mono">{{ fmt(r.quote?.close) }}</td><td :class="['number mono', direction(r.change_pct)]">{{ pct(r.change_pct) }}</td><td><span :class="['tag', r.exclusion_reasons.length ? 'amber' : 'green']">{{ r.exclusion_reasons.length ? '待核验' : '已核验' }}</span></td><td class="number">{{ r.budget ? r.budget.max_quantity + ' 股/份' : '—' }}</td></tr></tbody></table></div></section><section class="panel candidate-panel"><div class="panel-heading"><div><h2>今日研究候选</h2><p>至多 3 只，宁缺毋滥</p></div><Sparkles :size="18" class="muted" /></div><div v-if="!dashboard?.candidates.length" class="candidate-empty"><div class="empty-orbit"><ShieldCheck :size="25" /></div><h3>{{ latestReport ? '今日无合格模拟候选' : '研究从核验开始' }}</h3><p>{{ latestReport ? '查看报告，了解每只证券的排除原因。' : '同步行情并核验交易状态后，生成第一份研究报告。' }}</p><button class="text-button" @click="latestReport ? reportRoute(latestReport.id) : go('jobs')">{{ latestReport ? '查看筛选记录' : '查看准备事项' }} <ArrowRight :size="14" /></button></div><div v-else v-for="(c, i) in dashboard.candidates" :key="c.instrument_id" class="mini-candidate" @click="openDetail(c.instrument_id)"><span class="candidate-rank">0{{ Number(i) + 1 }}</span><div><strong>{{ c.name }}</strong><small>含费 ¥{{ fmt(c.budget.total) }} · {{ c.quantity }} 股/份</small></div><span class="score">{{ c.score }}<small>规则分</small></span></div></section></div>
          <section class="panel recent-panel"><div class="panel-heading"><div><h2>研究档案</h2><p>独立存档，收盘更新不会改写早报</p></div><button class="text-button" @click="go('reports')">全部报告 <ArrowRight :size="14" /></button></div><div v-if="!dashboard?.reports.length" class="empty-inline"><FileText :size="21" /><div><strong>还没有研究报告</strong><p>完成首次同步后，点击「生成研究报告」。模型离线时仍会生成规则型报告。</p></div><span class="small-badge">标准版 / 完整版</span></div><div v-for="r in dashboard?.reports.slice(0, 3)" :key="r.id" class="report-list-row" @click="reportRoute(r.id)"><span class="report-icon"><FileText :size="18" /></span><div><strong>{{ r.summary }}</strong><small>{{ modeNames[r.mode] }} · {{ dt(r.generated_at) }}</small></div><span class="tag">{{ r.candidate_count }} 只候选</span><ChevronRight :size="16" /></div></section>
        </template>

        <template v-else-if="page === 'watchlist' || page === 'market'">
          <section v-if="page === 'market'" class="panel"><div class="panel-heading"><h2>指数研究</h2><select v-model="activeIndex"><option v-for="i in indices" :key="i.id" :value="i.id">{{ i.name }}</option></select></div><ResearchChart :bars="indexData?.bars || []" :indicators="indexData?.indicators.series || []" /></section>
          <section class="panel watch-full"><div class="filter-toolbar"><div class="search-box"><Search :size="16" /><input v-model="search" aria-label="搜索证券" placeholder="搜索名称、代码或分组" /></div><select v-model="group" aria-label="分组"><option v-for="g in groups" :key="g">{{ g }}</option></select><select v-model="statusFilter" aria-label="状态"><option>全部</option><option>待核验</option><option>已核验</option></select><div class="toolbar-spacer"></div><button class="secondary small" :disabled="!canEdit" @click="importFile?.click()"><Plus :size="14" />导入</button><button class="secondary small" @click="exportData('/watchlist/export?format=csv', 'StockAI自选.csv')"><ArrowDownToLine :size="14" />CSV</button><button class="secondary small" @click="exportData('/watchlist/export', 'StockAI自选.json')">JSON</button><input hidden ref="importFile" type="file" accept=".json,.csv" @change="readFile($event, 'watch')" /></div><div class="table-scroll"><table class="watch-table full-table"><thead><tr><th></th><th>证券 / 代码</th><th>分组</th><th class="number">最近价格</th><th class="number">涨跌幅</th><th>风险状态</th><th class="number">¥1000 预算估算</th><th>来源 / 报价时间</th><th></th></tr></thead><tbody><tr v-for="r in filteredWatch" :key="r.id"><td><button class="icon-button" :disabled="!canEdit" @click="pin(r)" :aria-label="r.pinned ? '取消置顶' : '置顶'"><Star :size="15" :class="{ 'pinned-star': r.pinned }" /></button></td><td><button class="security-name" @click="openDetail(r.id)">{{ r.name }}</button><small>{{ r.symbol }} · {{ r.market }}</small></td><td><button class="group-button" :disabled="!canEdit" @click="editGroup(r)">{{ r.group_name }}</button></td><td class="number mono">{{ fmt(r.quote?.close ?? r.quote?.price, r.asset_class === 'etf' ? 3 : 2) }}</td><td :class="['number mono', direction(r.change_pct)]">{{ pct(r.change_pct) }}</td><td><span :class="['tag', !r.exclusion_reasons.length ? 'green' : r.risk_flag === 'st' || r.status === 'delisted' ? 'red' : 'amber']" :title="r.exclusion_reasons.join('；')">{{ r.observation_only ? '仅观察' : r.risk_flag === 'st' ? 'ST风险' : r.status === 'delisted' ? '已退市' : r.status === 'suspended' ? '停牌' : r.exclusion_reasons.length ? '待核验' : '已核验' }}</span></td><td class="number">{{ r.budget ? r.budget.max_quantity : '—' }}<small>{{ r.budget ? (r.exclusion_reasons.length ? '仅数学试算' : '含费预算估算') : '缺少行情' }}</small></td><td class="source-cell"><span>{{ r.quote?.source || '未获取' }}</span><small>{{ r.quote ? dt(r.quote.ts) : '—' }}</small></td><td><button class="icon-button" :disabled="!canEdit" @click="remove(r)" aria-label="移除自选"><Trash2 :size="15" /></button></td></tr></tbody></table></div><div v-if="!filteredWatch.length" class="empty-inline">没有符合条件的证券</div><div class="table-footer">共 {{ filteredWatch.length }} 项 · 初始名称来自需求清单，最新名称和交易资格须分别核验。</div></section>
        </template>

        <template v-else-if="page === 'metals'">
          <div class="metal-card-grid"><section v-for="(m, idx) in dashboard?.metals" :key="m.id" class="panel metal-card"><div class="metal-card-top"><span :class="['metal-symbol', { silver: Number(idx) % 2 === 1 }]">{{ Number(idx) % 2 ? 'Ag' : 'Au' }}</span><span class="tag">{{ Number(idx) < 2 ? '国际现货' : '期货连续合约' }}</span></div><h2>{{ metalNames[m.id] }}</h2><p>{{ m.id }}</p><div class="metal-card-price">{{ fmt(m.price) }}<span>{{ m.currency || (Number(idx) < 2 ? 'USD' : 'CNY') }}</span></div><div class="metal-meta"><span>计价单位</span><strong>{{ m.unit || (Number(idx) < 2 ? '美元/金衡盎司' : Number(idx) === 2 ? '元/克' : '元/千克') }}</strong><span>报价时间</span><strong>{{ dt(m.quote_time) }}</strong><span>采集时间</span><strong>{{ dt(m.fetched_at) }}</strong><span>延迟说明</span><strong>{{ m.delay_type || '数据不可用' }}</strong><span>来源</span><a v-if="m.source_url" :href="m.source_url" target="_blank" rel="noopener">{{ m.source }}</a><strong v-else>未获取</strong></div><div :class="['data-status', { warning: m.stale }]">{{ m.price ? m.stale ? '报价已超过24小时，请重新同步' : '已取得来源报价' : m.message }}</div></section></div><section class="panel prose-panel"><h2>同是金银，报价口径不同</h2><p>伦敦现货以美元/金衡盎司计价；沪金以元/克、沪银以元/千克计价。期货连续合约包含换月与期限结构影响，不能当作现货价格直接比较。金银比仅在同币种、同单位、同一报价时点下计算。</p><h3>贵金属关联 A 股</h3><div class="related-chips"><button v-for="r in watchlist.filter(r => r.group_name === '贵金属关联')" :key="r.id" @click="openDetail(r.id)">{{ r.name }}<small>{{ r.symbol }}</small><ArrowUpRight :size="14" /></button></div></section>
        </template>

        <template v-else-if="page === 'candidates'">
          <div class="info-strip"><ShieldCheck :size="19" /><span>交易状态、官方公告、行情新鲜度、流动性与单只含费预算全部通过，才进入候选。评分为规则匹配程度，不是上涨概率。</span></div><div v-if="!dashboard?.candidates.length" class="panel large-empty"><ShieldCheck :size="37" /><h2>今日无合格模拟候选</h2><p>宁可保留观察，也不把未知写成安全。先同步行情，并在证券详情核验官方证据。</p><button class="secondary" @click="go('watchlist')">查看观察池 <ArrowRight :size="15" /></button></div><div v-else class="candidate-grid"><section v-for="c in dashboard.candidates" :key="c.instrument_id" class="panel candidate-card"><div class="panel-heading"><h2>{{ c.name }} <small>{{ c.symbol }}</small></h2><b class="score">{{ c.score }}</b></div><div class="candidate-cost"><span>模拟 {{ c.quantity }} 股/份</span><strong>¥{{ fmt(c.budget.total) }}<small>含买入费用 ¥{{ fmt(c.budget.fees.total) }}</small></strong></div><h3>研究理由</h3><p>{{ c.rationale }}</p><h3>反方观点</h3><p>{{ c.counterargument }}</p><h3>失效条件</h3><p>{{ c.invalidation }}</p><small>{{ dt(c.quote_time) }} · <a :href="c.source_url" target="_blank" rel="noopener">行情来源</a></small><button class="secondary" :disabled="!canEdit" @click="prepareOrder(c.instrument_id)">创建模拟计划 <ArrowRight :size="15" /></button></section></div><section v-if="reports.length" class="panel prose-panel"><h2>查看完整排除依据</h2><p>报告逐只保留未入选原因与当时的事实快照。</p><button class="text-button" @click="reportRoute(reports[0].id)">打开最近报告 <ArrowRight :size="14" /></button></section>
        </template>

        <template v-else-if="page === 'reports' || page === 'review'">
          <template v-if="selectedReport"><button class="text-button back-button" @click="selectedReport = null"><ChevronLeft :size="16" />返回报告列表</button><section class="panel report-document"><div class="report-document-top"><div><span class="eyebrow">RESEARCH ARCHIVE</span><h2>{{ modeNames[selectedReport.mode] }}</h2><p>{{ selectedReport.report_date }} · {{ dt(selectedReport.generated_at) }} · Asia/Shanghai</p></div><div class="button-row"><button v-for="f in ['md', 'html', 'json']" :key="f" class="secondary small" @click="exportData('/reports/' + selectedReport.id + '/export?format=' + f, 'StockAI-' + selectedReport.report_date + '.' + f)"><ArrowDownToLine :size="13" />{{ f.toUpperCase() }}</button></div></div><div class="report-evidence-strip"><span>模型 <b>{{ selectedReport.model }}</b></span><span>策略 <b>{{ selectedReport.strategy_version }}</b></span><span class="tag" :class="selectedReport.ai_status === 'fallback' ? 'amber' : 'green'">{{ selectedReport.ai_status === 'fallback' ? '规则型报告' : 'AI解释已校验' }}</span></div><p v-if="selectedReport.ai_error" class="data-status warning">{{ selectedReport.ai_error }}</p><div v-if="props.publicMode" class="report-version-controls"><span class="tag">第 {{ selectedReport.version }} 版</span><button v-for="v in selectedReport.versions" :key="v.id" class="secondary small" :disabled="v.id === selectedReport.id" @click="showReport(v.id)">版本 {{ v.version }}</button><button class="primary small" :disabled="busy" @click="supplementReport">补充 AI / 生成新版本</button><small>原始事实快照保持不变 · 使用本人当前默认配置</small></div><h2>{{ selectedReport.summary }}</h2><p class="report-lead">{{ selectedReport.market_context }}</p><h3>研究候选 · {{ selectedReport.candidates.length }} 只</h3><p v-if="!selectedReport.candidates.length">今日无合格模拟候选。</p><div v-for="c in selectedReport.candidates" :key="c.instrument_id" class="report-candidate"><h3>{{ c.name }} {{ c.symbol }}</h3><p>报价 ¥{{ fmt(c.price) }} · {{ dt(c.quote_time) }} · {{ c.quantity }} 股/份 · 含费 ¥{{ fmt(c.budget.total) }}</p><p>{{ c.rationale }}</p><p><strong>反方观点：</strong>{{ c.counterargument }}</p><p><strong>失效条件：</strong>{{ c.invalidation }}</p></div><h3>风险与缺失数据</h3><ul><li v-for="(r, idx) in [...selectedReport.risk_notes, ...selectedReport.missing_data]" :key="idx">{{ r }}</li></ul><h3>未入选记录</h3><div class="table-scroll"><table class="watch-table exclusion-table"><thead><tr><th>证券</th><th>排除原因</th></tr></thead><tbody><tr v-for="r in selectedReport.excluded" :key="r.instrument_id"><td><button class="security-name" @click="openDetail(r.instrument_id)">{{ r.name }}</button><small>{{ r.instrument_id }}</small></td><td>{{ r.reasons.join('；') }}</td></tr></tbody></table></div><h3>原始证据 · {{ selectedReport.sources.length }} 项</h3><div v-for="s in selectedReport.sources" :key="s.id" class="source-row"><a :href="s.url" target="_blank" rel="noopener">[{{ s.id }}] {{ s.instrument_id }} · {{ s.source }}</a><small>报价 {{ dt(s.quote_time) }} · 采集 {{ dt(s.collected_at) }}</small></div><div class="snapshot-id">事实快照 SHA256 · {{ selectedReport.snapshot_id }}</div></section></template>
          <template v-else><div v-if="page === 'review'" class="stats-grid"><article class="metric-card"><div class="metric-label">已存复盘</div><div class="metric-value">{{ reports.length }}</div></article><article class="metric-card"><div class="metric-label">虚拟账户</div><div class="metric-value">{{ portfolio.accounts.length }}</div></article><article class="metric-card"><div class="metric-label">模拟成交</div><div class="metric-value">{{ portfolio.orders.filter((x: any) => x.status === 'filled').length }}</div></article><article class="metric-card"><div class="metric-label">已存回测</div><div class="metric-value">{{ experiments.length }}</div></article></div><section class="panel"><div class="filter-toolbar"><div class="segmented"><button v-for="m in ['', 'standard', 'full', 'closing']" :key="m" :class="{ selected: reportMode === m }" @click="reportMode = m">{{ m ? modeNames[m] : '全部报告' }}</button></div><div class="toolbar-spacer"></div><div class="search-box"><Search :size="15" /><input v-model="reportSearch" placeholder="搜索日期或研究结论" aria-label="搜索报告" /></div></div><div v-if="!visibleReports.length" class="large-empty"><FileText :size="34" /><h2>等待第一份研究档案</h2><p>标准版覆盖日常研究，完整版记录多周期与历史验证。证据不足会如实写入报告。</p></div><div v-for="r in visibleReports" :key="r.id" class="report-list-row" @click="showReport(r.id)"><span class="report-icon"><FileText :size="22" /></span><div><span class="tag">{{ modeNames[r.mode] }}</span><h3>{{ r.summary }}</h3><small>{{ dt(r.generated_at) }} · {{ r.ai_status === 'fallback' ? '规则型报告' : 'AI解释已校验' }}</small></div><span class="tag">{{ r.candidate_count }} 只候选</span><ChevronRight :size="17" /></div></section></template>
        </template>

        <template v-else-if="page === 'simulation'">
          <div class="info-strip"><Wallet :size="19" /><span>独立虚拟账户，初始资金由你设置。委托仅使用创建后形成的行情撮合；收盘触发止损在后续K线执行。</span><button class="text-button" :disabled="!canEdit" @click="openModal('account', { name: '', initial_cash: null })">新增账户 <Plus :size="14" /></button></div><div v-if="!portfolio.accounts.length" class="panel large-empty"><Wallet :size="36" /><h2>建立你的第一个模拟账户</h2><p>填写虚拟初始资金，不代表你的真实总资产。</p><button class="primary" :disabled="!canEdit" @click="openModal('account', { name: '我的模拟账户', initial_cash: null })"><Plus :size="16" />创建模拟账户</button></div><section v-for="a in portfolio.accounts" :key="a.id" class="panel account-panel"><div class="panel-heading"><h2>{{ a.name }} <span class="small-badge">虚拟账户</span></h2><small>创建于 {{ dt(a.created_at) }}</small></div><div class="account-metrics"><div><span>总权益（缓存估值）</span><b>¥{{ fmt(a.equity) }}</b></div><div><span>可用现金</span><b>¥{{ fmt(a.cash) }}</b></div><div><span>累计损益</span><b :class="direction(a.pnl)">¥{{ fmt(a.pnl) }}</b></div><div><span>初始虚拟资金</span><b>¥{{ fmt(a.initial_cash) }}</b></div></div><ResearchChart v-if="a.curve.length" kind="equity" :curve="a.curve" /><div class="table-scroll"><table class="watch-table"><thead><tr><th>持仓证券</th><th>持有 / 可卖数量</th><th class="number">含费成本</th><th class="number">缓存市值</th><th class="number">浮动损益</th><th>行情时间</th></tr></thead><tbody><tr v-for="p in a.positions" :key="p.instrument_id"><td><button class="security-name" @click="openDetail(p.instrument_id)">{{ p.name }}</button><small>{{ p.instrument_id }}</small></td><td>{{ p.quantity }} / {{ p.available_quantity }}</td><td class="number">{{ fmt(p.cost) }}</td><td class="number">{{ fmt(p.market_value) }}</td><td :class="['number', direction(p.unrealized_pnl)]">{{ fmt(p.unrealized_pnl) }}</td><td>{{ dt(p.quote_time) }} <span v-if="p.stale" class="tag amber">过期</span></td></tr></tbody></table></div><p v-if="!a.positions.length" class="empty-table">暂无持仓</p></section><section class="panel"><div class="filter-toolbar"><div class="segmented"><button :class="{ selected: accountTab === 'orders' }" @click="accountTab = 'orders'">模拟委托</button><button :class="{ selected: accountTab === 'ledger' }" @click="accountTab = 'ledger'">现金流水</button></div><div class="toolbar-spacer"></div><button class="secondary small" :disabled="busy || !canEdit" @click="runJob('match')"><RefreshCw :size="14" />按后续行情撮合</button></div><div class="table-scroll"><table v-if="accountTab === 'orders'" class="watch-table"><thead><tr><th>证券</th><th>方向 / 数量</th><th>限价 / 成交价</th><th>费用</th><th>状态</th><th>创建 / 成交时间</th><th></th></tr></thead><tbody><tr v-for="o in portfolio.orders" :key="o.id"><td>{{ o.name }}<small>{{ o.instrument_id }}</small></td><td :class="o.side === 'buy' ? 'up' : 'down'">{{ o.side === 'buy' ? '买入' : '卖出' }} {{ o.quantity }}</td><td>{{ fmt(o.limit_price) }} / {{ fmt(o.fill_price) }}</td><td>{{ fmt(o.fees) }}</td><td><span class="tag" :class="o.status === 'filled' ? 'green' : o.status === 'rejected' ? 'red' : ''">{{ statuses[o.status] }}</span><small>{{ o.reason }}</small></td><td>{{ dt(o.created_at) }}<small>{{ o.filled_at ? dt(o.filled_at) : '等待后续完整K线' }}</small></td><td><button v-if="o.status === 'pending'" class="text-button" :disabled="!canEdit" @click="action(async () => { await post('/orders/' + o.id + '/cancel'); await loadPage() })">撤销</button></td></tr></tbody></table><table v-else class="watch-table"><thead><tr><th>时间</th><th>说明</th><th class="number">变动</th><th class="number">余额</th><th>账户</th></tr></thead><tbody><tr v-for="l in portfolio.ledger" :key="l.id"><td>{{ dt(l.ts) }}</td><td>{{ l.description }}</td><td class="number">{{ fmt(l.delta) }}</td><td class="number">{{ fmt(l.balance) }}</td><td class="mono">{{ l.account_id.slice(0, 8) }}</td></tr></tbody></table></div><p v-if="accountTab === 'orders' && !portfolio.orders.length" class="empty-table">暂无模拟委托</p></section>
        </template>

        <template v-else-if="page === 'backtest'">
          <section class="panel"><div class="panel-heading"><div><h2>均线趋势策略</h2><p>收盘信号 → 下一根开盘成交 · 策略版本 2.0.0</p></div><span class="tag">确定性历史撮合</span></div><form class="experiment-form" @submit.prevent="runBacktest"><label class="wide-field">研究证券<select v-model="testParams.instrument_id"><option v-for="r in watchlist.filter(r => ['stock', 'etf'].includes(r.asset_class) && ['SH', 'SZ'].includes(r.market))" :key="r.id" :value="r.id">{{ r.name }} {{ r.symbol }}</option></select></label><label>虚拟初始资金<input type="number" min="1" step="0.01" required v-model.number="testParams.initial_cash" /></label><label>短均线<input type="number" min="2" max="100" required v-model.number="testParams.fast" /></label><label>长均线<input type="number" min="3" max="250" required v-model.number="testParams.slow" /></label><label>样本内比例<input type="number" min="0.5" max="0.9" step="0.05" required v-model.number="testParams.train_ratio" /></label><label>收盘止损比例<input type="number" min="0.01" max="0.5" step="0.01" required v-model.number="testParams.stop_loss_pct" /></label><label>开始日期<input type="date" v-model="testParams.start_date" /></label><label>结束日期<input type="date" v-model="testParams.end_date" /></label><label class="check-label"><input type="checkbox" v-model="testParams.strict" />严格证据模式</label><button class="primary" :disabled="busy || !canEdit"><FlaskConical :size="16" />{{ busy ? '计算中' : '运行回测' }}</button></form><div class="table-footer">严格模式需要逐日历史状态和公司行动证据；取消后仅作为未验证实验，始终保留数据缺口。</div></section>
          <section v-if="selectedBacktest" class="panel backtest-result"><div class="panel-heading"><h2>实验结果 <span :class="['tag', selectedBacktest.validated ? 'green' : 'amber']">{{ selectedBacktest.validated ? '证据完整' : '未验证实验' }}</span></h2><div class="button-row"><button class="secondary small" @click="action(async () => { const r = await post('/backtests/' + selectedBacktest.id + '/reproduce'); notify(r.identical ? '重演一致，快照与交易记录校验通过' : '重演不一致，请检查策略版本') })">快照重演</button><button class="secondary small" @click="exportData('/backtests/' + selectedBacktest.id + '/export', 'StockAI回测.json')"><ArrowDownToLine :size="14" />导出</button></div></div><div class="account-metrics"><div><span>全样本收益</span><b :class="direction(selectedBacktest.summary.return_pct)">{{ pct(selectedBacktest.summary.return_pct) }}</b></div><div><span>最大回撤</span><b>{{ fmt(selectedBacktest.summary.max_drawdown_pct) }}%</b></div><div><span>完整交易次数</span><b>{{ selectedBacktest.summary.round_trips }}</b></div><div><span>胜率 / 盈利因子</span><b>{{ fmt(selectedBacktest.summary.win_rate_pct) }}% / {{ fmt(selectedBacktest.summary.profit_factor) }}</b></div></div><ResearchChart kind="equity" :curve="selectedBacktest.full.equity" /><div class="table-scroll"><table class="watch-table"><thead><tr><th>验证区间</th><th>收益</th><th>回撤</th><th>完整交易</th><th>区间</th></tr></thead><tbody><tr v-for="(r, idx) in [selectedBacktest.in_sample, selectedBacktest.out_of_sample]" :key="idx"><td>{{ idx ? '样本外' : '样本内' }}</td><td>{{ pct(r.metrics.return_pct) }}</td><td>{{ fmt(r.metrics.max_drawdown_pct) }}%</td><td>{{ r.metrics.round_trips }}</td><td>{{ r.range[0].slice(0, 10) }} — {{ r.range[1].slice(0, 10) }}</td></tr></tbody></table></div><div class="prose-panel"><h3>成本敏感性</h3><div class="sensitivity-grid"><div v-for="c in selectedBacktest.cost_sensitivity" :key="c.fee_multiplier"><small>{{ c.fee_multiplier }} 倍费用</small><strong>{{ pct(c.metrics.return_pct) }}</strong><small>累计费用 ¥{{ fmt(c.metrics.fees) }}</small></div></div><h3>可复核交易</h3><div class="table-scroll"><table class="watch-table"><thead><tr><th>信号时间</th><th>成交时间</th><th>方向</th><th>数量</th><th>价格</th><th>费用</th><th>现金</th></tr></thead><tbody><tr v-for="(t, idx) in selectedBacktest.full.trades" :key="idx"><td>{{ dt(t.signal_ts) }}</td><td>{{ dt(t.ts) }}</td><td>{{ t.side === 'buy' ? '买' : '卖' }}</td><td>{{ t.quantity }}</td><td>{{ fmt(t.price) }}</td><td>{{ fmt(t.fees) }}</td><td>{{ fmt(t.cash) }}</td></tr></tbody></table></div><h3>解释边界与缺失证据</h3><p v-for="w in selectedBacktest.warnings" :key="w" class="warning-text">{{ w }}</p><small>{{ selectedBacktest.full.execution }}</small><div class="snapshot-id">数据 SHA256 · {{ selectedBacktest.data_hash }}</div></div></section>
          <section class="panel"><div class="panel-heading"><h2>实验档案</h2><span class="muted">{{ experiments.length }} 次</span></div><div v-if="!experiments.length" class="empty-inline"><FlaskConical :size="22" /><span>还没有历史实验。需要先获取足够的真实历史K线。</span></div><div v-for="r in experiments" :key="r.id" class="report-list-row" @click="action(async () => selectedBacktest = await api('/backtests/' + r.id))"><span class="report-icon"><FlaskConical :size="20" /></span><div><strong>{{ r.params.instrument_id }} · MA{{ r.params.fast }} / MA{{ r.params.slow }}</strong><small>{{ dt(r.created_at) }} · {{ r.validated ? '证据完整' : '未验证实验' }}</small></div><span :class="direction(r.summary.return_pct)">{{ pct(r.summary.return_pct) }}</span><ChevronRight :size="16" /></div></section>
        </template>

        <template v-else-if="page === 'jobs'">
          <div class="schedule-grid"><section v-for="p in jobData.schedule.plans" :key="p.kind" class="panel schedule-card"><span :class="['schedule-icon', { gold: p.kind === 'full' }]"><component :is="p.kind === 'full' ? BookOpen : p.kind === 'standard' ? Sparkles : ChartCandlestick" :size="20" /></span><strong>{{ p.label }}</strong><div class="schedule-time">{{ p.time }}<small>Asia/Shanghai</small></div><p>{{ p.rule }}</p><button class="text-button" :disabled="busy || !canEdit" @click="runJob(p.kind)">手动补跑 <ArrowRight :size="14" /></button></section></div><div class="info-strip"><Clock3 :size="18" /><span>唯一调度源：内建调度器 · {{ jobData.schedule.enabled ? '已开启' : '已关闭' }}。恢复运行后补跑当天到期任务，同一日期同一类型不会重复归档。</span><button class="text-button" @click="go('settings')">配置</button></div><section class="panel"><div class="panel-heading"><h2>任务记录</h2><div class="button-row"><button v-if="canMaintain" class="secondary small" :disabled="busy" @click="runJob('sync')"><RefreshCw :size="14" />数据同步</button><button class="secondary small" @click="loadPage"><RefreshCw :size="14" />刷新</button></div></div><div class="table-scroll"><table class="watch-table"><thead><tr><th>任务</th><th>状态</th><th>开始 / 完成</th><th>尝试次数</th><th>错误 / 幂等键</th><th></th></tr></thead><tbody><tr v-for="j in jobData.jobs" :key="j.id"><td>{{ modeNames[j.kind] }}</td><td><span :class="['tag', ['failed', 'interrupted', 'missed'].includes(j.status) ? 'red' : j.status === 'success' ? 'green' : 'amber']"><LoaderCircle v-if="j.status === 'running'" class="spin" :size="11" />{{ statuses[j.status] }}</span></td><td>{{ dt(j.started_at) }}<small>{{ j.finished_at ? dt(j.finished_at) : '—' }}</small></td><td>{{ j.attempts }}</td><td class="error-cell">{{ j.error || j.logical_key }}</td><td><button v-if="['failed', 'partial', 'interrupted', 'missed'].includes(j.status)" class="text-button" :disabled="busy || !canEdit" @click="action(async () => { await post('/jobs/' + j.id + '/retry'); await loadPage() })">重试</button></td></tr></tbody></table></div><p v-if="!jobData.jobs.length" class="empty-table">尚无任务记录</p></section><section class="panel"><div class="panel-heading"><h2>运行日志</h2><Terminal :size="17" class="muted" /></div><div class="log-view"><p v-if="!jobData.logs.length">等待任务运行…</p><div v-for="l in jobData.logs" :key="l.id" :class="{ 'log-error': l.level === 'error' }"><time>{{ dt(l.ts) }}</time><span>{{ l.level.toUpperCase() }}</span>{{ l.message }}</div></div></section>
        </template>

        <template v-else-if="page === 'settings' && config">
          <div class="settings-grid"><section class="panel settings-panel"><div class="panel-heading"><div><h2>本地 AI</h2><p>结构化事实输入，中文解释输出</p></div><Activity :size="18" /></div><div class="form-grid"><label class="span-two">Ollama 地址<input v-model="config.ollama_url" type="url" /></label><label class="span-two">模型名称<input v-model="config.model" /></label><label>调用超时（秒）<input v-model.number="config.ai_timeout" type="number" min="10" max="600" /></label><label class="check-label"><input type="checkbox" v-model="config.ai_enabled" />启用 AI 解释</label></div><div :class="['data-status', { warning: !model.available }]">{{ model.message }}</div><button class="text-button" @click="action(async () => model = await api('/model/health'))"><RefreshCw :size="14" />检查模型</button></section><section class="panel settings-panel"><div class="panel-heading"><div><h2>预算与费用假设</h2><p>全部费用以人民币估算</p></div><Wallet :size="18" /></div><div class="form-grid"><label>单只含费预算（≤1000）<input type="number" min="1" max="1000" v-model.number="config.budget" /></label><label>滑点（基点）<input type="number" min="0" max="500" v-model.number="config.fees.slippage_bps" /></label><label>股票佣金率<input type="number" step="0.00001" v-model.number="config.fees.stock_commission" /></label><label>股票最低佣金<input type="number" step="0.01" v-model.number="config.fees.stock_minimum" /></label><label>ETF 佣金率<input type="number" step="0.00001" v-model.number="config.fees.etf_commission" /></label><label>ETF 最低佣金<input type="number" step="0.01" v-model.number="config.fees.etf_minimum" /></label><label>股票过户费率<input type="number" step="0.00001" v-model.number="config.fees.stock_transfer" /></label><label>股票卖出印花税率<input type="number" step="0.00001" v-model.number="config.fees.stock_stamp_sell" /></label><label class="check-label span-two"><input type="checkbox" v-model="config.fees.confirmed" />已按券商及产品规则核对费率</label><label class="span-two">费用说明<textarea v-model="config.fees.note" rows="2"></textarea></label></div></section><section class="panel settings-panel"><div class="panel-heading"><div><h2>采集与任务计划</h2><p>唯一调度源 · Asia/Shanghai</p></div><Clock3 :size="18" /></div><div class="form-grid"><label>早报<input type="time" v-model="config.morning_time" /></label><label>收盘跟踪<input type="time" v-model="config.closing_time" /></label><label>周日复盘<input type="time" v-model="config.weekly_time" /></label><label class="check-label"><input type="checkbox" v-model="config.scheduler_enabled" />启用内建调度</label><label>最低日成交额（元）<input type="number" min="0" v-model.number="config.min_daily_amount" /></label><label>风险核验有效期（小时）<input type="number" min="1" max="72" v-model.number="config.max_risk_age_hours" /></label></div><p class="help-text">主数据来自交易所渠道，日线主源为东方财富、股票备用源为新浪；接口失败按未知处理。电脑关闭期间不会执行任务。</p></section><section class="panel settings-panel"><div class="panel-heading"><div><h2>访问与安全</h2><p>局域网访问默认关闭</p></div><LockKeyhole :size="18" /></div><div class="form-grid"><label class="check-label span-two"><input type="checkbox" v-model="config.lan_enabled" />开启已鉴权的局域网访问（需重启）</label><label class="span-two">允许的内网来源（CIDR，以逗号分隔）<input :value="config.allowed_networks.join(', ')" @change="config.allowed_networks = ($event.target as HTMLInputElement).value.split(',').map(x => x.trim()).filter(Boolean)" /></label></div><label class="proxy-label">内网反向代理主机名（可选）<input v-model="config.proxy_hostname" placeholder="research.home.arpa" /></label><p class="help-text">当前监听：{{ runtime.runtime_host }}。启用前必须设置管理员密码，防火墙仅放行指定网段与服务端口；Ollama 仍只允许本机连接。</p><div class="button-row"><button class="secondary small" :disabled="!canEdit" @click="openModal('password', { role: 'admin', password: '' })">设置访问密码</button><span class="tag" :class="runtime.lan_auth_configured ? 'green' : 'amber'">{{ runtime.lan_auth_configured ? '鉴权已配置' : '鉴权未配置' }}</span></div></section><section class="panel settings-panel"><div class="panel-heading"><div><h2>邮件通知</h2><p>配置后生效，界面通知始终保存</p></div><Bell :size="18" /></div><div class="form-grid"><label class="check-label span-two"><input type="checkbox" v-model="config.email_enabled" />启用邮件通知</label><label>SMTP 服务器<input v-model="config.smtp_host" /></label><label>SSL 端口<input type="number" v-model.number="config.smtp_port" /></label><label>发件用户<input v-model="config.smtp_user" /></label><label>接收邮箱<input v-model="config.email_to" type="email" /></label></div><p class="help-text">密码只从服务进程环境变量 STOCKAI_SMTP_PASSWORD 读取，不写入配置或传入模型。</p></section><section class="panel settings-panel"><div class="panel-heading"><div><h2>数据管理</h2><p>数据库、研究报告与快照一同备份</p></div><Database :size="18" /></div><div class="button-row"><button class="secondary" :disabled="busy || !canEdit" @click="action(async () => { await post('/backups'); backups = await api('/backups'); notify('备份完成，完整性与关联校验通过') })"><Database :size="15" />创建备份</button><button class="secondary" @click="exportData('/config/export', 'StockAI配置.json')"><ArrowDownToLine :size="15" />导出配置</button><label class="secondary file-button">导入配置<input type="file" accept=".json" :disabled="!canEdit" @change="readFile($event, 'config')" /></label></div><div v-for="b in backups.slice(0, 6)" :key="b.id" class="backup-row"><div><strong>{{ dt(b.created_at) }}</strong><small>{{ fmt(b.size / 1024, 1) }} KB · {{ b.counts?.reports || 0 }} 份报告</small></div><button class="text-button" @click="exportData('/backups/' + b.id + '/download', 'StockAI备份-' + b.id + '.zip')">下载</button><button class="text-button danger-text" :disabled="!canEdit" @click="openModal('restore', { id: b.id, confirmation: '' })">恢复</button></div><p v-if="!backups.length" class="help-text">尚无备份。每周日复盘后也会创建自动备份。</p></section></div>
        </template>
        <footer class="page-footer"><span><ShieldCheck :size="13" />仅供研究与模拟交易 · 不接入真实账户</span><span>数据有出处，判断有边界 <span class="footer-dot">·</span> StockAI {{ props.publicMode ? "3.0" : "2.0" }}</span></footer>
      </main>
    </div>
    <div v-if="toast" class="toast" role="status"><Check :size="17" />{{ toast }}</div>
    <div v-if="detailId" class="drawer-scrim" @click.self="detailId = ''; detail = null"><section class="detail-drawer" role="dialog" aria-modal="true" aria-label="证券详情"><header class="drawer-heading"><button class="text-button" @click="detailId = ''; detail = null"><ChevronLeft :size="17" />返回研究</button><button class="icon-button" @click="detailId = ''; detail = null" aria-label="关闭详情"><X :size="20" /></button></header><div v-if="!detail" class="large-empty"><LoaderCircle class="spin" /></div><template v-else><div class="detail-title"><div><span class="eyebrow">INSTRUMENT RESEARCH</span><h2>{{ detail.instrument.name }}</h2><p>{{ detail.instrument.symbol }} · {{ detail.instrument.market }} · {{ detail.instrument.group_name }}</p></div><span class="tag" :class="detail.risk_reasons.length ? 'amber' : 'green'">{{ detail.risk_reasons.length ? '交易资格待核验' : '已核验' }}</span></div><div class="detail-price"><strong>{{ fmt(detail.bars.at(-1)?.close ?? detail.observation?.price, detail.instrument.asset_class === 'etf' ? 3 : 2) }}</strong><span>{{ dt(detail.bars.at(-1)?.ts || detail.observation?.quote_time) }} · {{ detail.observation?.unit || '已完成K线' }}</span></div><div class="filter-toolbar detail-chart-tools"><div class="segmented"><button v-for="tf in ['1d', '1w', '60m', '15m']" :key="tf" :class="{ selected: timeframe === tf }" @click="changeTimeframe(tf)">{{ { '1d': '日线', '1w': '周线', '60m': '60分钟', '15m': '15分钟' }[tf] }}</button></div><select v-model="lowerIndicator" aria-label="附图指标"><option value="volume">成交量</option><option value="macd">MACD</option><option value="rsi">RSI14</option><option value="atr">ATR14</option></select><button class="icon-button" :disabled="busy || !canEdit" v-if="canMaintain" aria-label="同步当前周期" @click="action(async () => { const r = await post('/instruments/' + encodeURIComponent(detailId) + '/sync', { timeframe: timeframe === '1w' ? '1d' : timeframe }); notify(r.status === 'success' ? '同步成功' : r.message); await changeTimeframe(timeframe); await refreshBase() })"><RefreshCw :size="16" /></button></div><ResearchChart :bars="detail.bars" :indicators="detail.indicators.series" :indicator="lowerIndicator" /><div class="detail-source">{{ detail.bars.at(-1)?.source || detail.observation?.source || '行情不可用' }} · {{ detail.observation ? (detail.observation.timestamp_basis || '报价快照') : detail.bars.at(-1)?.adjustment === 'none' ? '不复权' : '复权口径待核验' }} · <a v-if="detail.bars.length || detail.observation" :href="detail.bars.at(-1)?.source_url || detail.observation?.source_url" target="_blank" rel="noopener">来源证据</a><button v-if="canMaintain" class="text-button" :disabled="busy" @click="barsFile?.click()">导入历史 JSON</button><input ref="barsFile" hidden type="file" accept=".json" @change="readFile($event, 'bars')" /></div><div class="indicator-grid"><div v-for="key in ['ma5', 'ma20', 'ma60', 'rsi14', 'atr14', 'volatility20', 'support20', 'resistance20']" :key="key"><small>{{ { ma5: 'MA5', ma20: 'MA20', ma60: 'MA60', rsi14: 'RSI14', atr14: 'ATR14', volatility20: '20日年化波动率%', support20: '20周期支撑参考', resistance20: '20周期阻力参考' }[key] }}</small><strong>{{ fmt(detail.indicators.latest[key]) }}</strong></div></div><section class="detail-section"><div class="panel-heading"><h3>交易资格与官方证据</h3><button v-if="canMaintain" class="text-button" :disabled="busy" @click="verifyForm">核验记录 <ArrowRight :size="14" /></button></div><p v-for="r in detail.risk_reasons" :key="r" class="risk-line"><span class="tiny-dot amber"></span>{{ r }}</p><p v-if="!detail.risk_reasons.length" class="green-text">已通过核验 · {{ dt(detail.instrument.verified_at) }}</p><small>名称、上市状态、停复牌、公告与产品规则独立核对，不由模型判断安全。</small></section><section v-if="['SH', 'SZ'].includes(detail.instrument.market) && ['stock', 'etf'].includes(detail.instrument.asset_class)" class="detail-section"><h3>¥1000 含费预算试算</h3><form class="budget-form" @submit.prevent="estimate"><label>成交价格<input type="number" min="0.001" step="0.001" v-model.number="budgetForm.price" required /></label><label>模拟数量<input type="number" min="1" v-model.number="budgetForm.quantity" required /></label><button class="secondary" :disabled="busy">计算</button></form><div v-if="budget" class="budget-result"><div><span>成交金额</span><b>¥{{ fmt(budget.gross) }}</b></div><div><span>预计买入费用</span><b>¥{{ fmt(budget.fees.total) }}</b></div><div><span>含费总成本</span><b>¥{{ fmt(budget.total) }}</b></div><span :class="['tag', budget.within_budget ? 'green' : 'red']">{{ budget.within_budget ? '通过预算门槛' : '超预算，拒绝模拟买入' }}</span><p>{{ budget.fee_note }} {{ budget.eligible ? '' : '预算通过不等于交易资格通过。' }}</p><small>最低佣金敏感性：{{ budget.sensitivity.map((s: any) => '佣金底限¥' + s.minimum_commission + ' → 总成本¥' + s.total).join('；') }}</small></div></section><section class="detail-section"><div class="panel-heading"><h3>公告与风险记录</h3><button v-if="canMaintain" class="text-button" :disabled="busy" @click="action(async () => { await post('/instruments/' + encodeURIComponent(detailId) + '/announcements'); await changeTimeframe(timeframe); notify('公告已同步，仍需核对停复牌与产品规则') })">同步官方公告 <RefreshCw :size="14" /></button></div><div v-for="e in detail.events" :key="e.id" class="event-row"><a :href="e.source_url" target="_blank" rel="noopener">{{ e.title }}</a><small>{{ dt(e.verified_at) }} · {{ e.event_type === 'manual_official_review' ? '人工官方核验' : '公告采集记录' }}</small></div><p v-if="!detail.events.length" class="muted">暂无已归档公告，不能默认为没有风险。</p></section></template></section></div>

    <div v-if="modal" class="modal-scrim" @click.self="!busy && (modal = '')"><form class="modal" :class="{ 'wide-modal': modal === 'verify' }" role="dialog" aria-modal="true" :aria-label="({ add: '添加证券', account: '创建模拟账户', order: '模拟委托', password: '访问密码', restore: '恢复备份', verify: '官方证据核验' } as any)[modal]" @submit.prevent="submitModal"><div class="modal-heading"><h2>{{ ({ add: '添加证券', account: '创建模拟账户', order: '创建模拟委托', password: '设置访问密码', restore: '恢复备份', verify: '记录官方核验证据' } as any)[modal] }}</h2><button type="button" class="icon-button" @click="modal = ''" aria-label="关闭"><X :size="19" /></button></div><p v-if="modalError" class="inline-error" role="alert">{{ modalError }}</p>
      <template v-if="modal === 'add'"><div class="form-grid"><label>市场<select v-model="form.market"><option v-for="m in ['SH', 'SZ', 'HK', 'US', 'FUND']" :key="m">{{ m }}</option></select></label><label>资产类别<select v-model="form.asset_class"><option value="stock">股票</option><option value="etf">场内ETF</option><option value="fund">场外基金</option><option value="index">指数</option></select></label><label>证券代码<input v-model="form.symbol" required /></label><label>历史/备注名称<input v-model="form.name" required /></label><label class="span-two">分组<input v-model="form.group_name" required /></label></div><p class="help-text">按市场与代码去重。新添加的证券状态为未核验，不直接进入候选。</p></template>
      <template v-if="modal === 'account'"><label>账户名称<input v-model="form.name" required maxlength="80" /></label><label>虚拟初始资金（人民币）<input v-model.number="form.initial_cash" type="number" min="0.01" max="100000000" step="0.01" required placeholder="请自行填写" /></label><p class="help-text">这是一笔虚拟资金，不代表真实账户资产。</p></template>
      <template v-if="modal === 'order'"><label>虚拟账户<select v-model="form.account_id" required><option v-for="a in portfolio.accounts" :key="a.id" :value="a.id">{{ a.name }} · 现金 ¥{{ fmt(a.cash) }}</option></select></label><label>证券<select v-model="form.instrument_id" required><option v-for="r in watchlist.filter(r => ['SH', 'SZ'].includes(r.market) && ['stock', 'etf'].includes(r.asset_class))" :key="r.id" :value="r.id">{{ r.name }} {{ r.symbol }}</option></select></label><div class="form-grid"><label>方向<select v-model="form.side"><option value="buy">模拟买入</option><option value="sell">模拟卖出</option></select></label><label>数量<input type="number" min="1" required v-model.number="form.quantity" /></label><label>限价<input type="number" min="0.001" step="0.001" required v-model.number="form.limit_price" /></label><label v-if="form.side === 'buy'">收盘止损价（可选）<input type="number" step="0.001" v-model.number="form.stop_loss" /></label></div><p class="help-text">提交后进入待成交队列，不会用创建前的历史行情立即成交。买入总成本含费不得超过单只预算。</p></template>
      <template v-if="modal === 'password'"><label>角色<select v-model="form.role"><option value="admin">管理员</option><option value="reader">只读访问者</option></select></label><label>访问密码<input type="password" v-model="form.password" minlength="12" maxlength="200" required autocomplete="new-password" /></label><p class="help-text">至少12位。修改密码会使已有局域网会话失效。</p></template>
      <template v-if="modal === 'restore'"><p>此操作将替换当前数据库与配置。程序会先保留恢复前备份，再校验记录数量和关联关系。</p><label>键入“恢复备份”确认<input v-model="form.confirmation" required pattern="恢复备份" autocomplete="off" /></label></template>
      <template v-if="modal === 'verify'"><p class="help-text">请实际打开并核对官方来源。仅粘贴首页链接不能证明交易状态安全，核验记录会带时间保存。</p><div class="form-grid"><label>最新官方名称<input v-model="form.name" required /></label><label>交易状态<select v-model="form.status"><option value="active">正常上市交易</option><option value="suspended">停牌</option><option value="delisted">已退市</option><option value="unknown">未知</option></select></label><label>风险核验<select v-model="form.risk_flag"><option value="clear">已核对，无已知警示</option><option value="st">ST / *ST</option><option value="warning">存在风险公告</option><option value="unknown">未知</option></select></label><label>最小买入数量<input type="number" min="1" v-model.number="form.rules.lot_size" required /></label><label>数量阶梯<input type="number" min="1" v-model.number="form.rules.quantity_step" required /></label><label>价格最小步长<input v-model="form.rules.price_tick" required /></label><label>卖出交收限制<select v-model.number="form.rules.settlement_days"><option :value="1">T+1</option><option :value="0">T+0（须产品支持）</option></select></label><label>常规涨跌幅限制<input type="number" min="0.01" max="0.5" step="0.01" v-model.number="form.rules.limit_pct" required /></label><label class="span-two">官方产品规则链接<input type="url" v-model="form.rules.source_url" required /></label><label class="span-two">官方上市与名称证据<input type="url" v-model="form.evidence.listing_url" required /></label><label class="span-two">官方停复牌状态证据<input type="url" v-model="form.evidence.status_url" required /></label><label class="span-two">官方公告核查证据<input type="url" v-model="form.evidence.announcement_url" required /></label><label class="span-two">人工核对结论<textarea v-model="form.evidence.review_note" rows="3" required></textarea></label><label class="check-label span-two"><input type="checkbox" v-model="form.rules.verified" required />我已核对上述证据与该产品适用的交易规则</label></div></template>
      <div class="modal-actions"><button type="button" class="secondary" :disabled="busy" @click="modal = ''">取消</button><button class="primary" :disabled="busy"><LoaderCircle v-if="busy" class="spin" :size="15" />{{ modal === 'restore' ? '确认恢复' : '保存' }}</button></div>
    </form></div>
  </div>
  <ConfirmDialog :message="confirmText" @choose="settleConfirm" />
</template>
